var TEMAS=[
tema('materia','Materia: estados y cambios',
 {curiosos:['El agua es la única sustancia que se encuentra de forma natural en los tres estados en la Tierra, y el hielo flota porque es menos denso que el agua líquida.','En Bogotá el agua hierve a unos 92 °C y no a 100 °C, porque la presión atmosférica es menor.'],
  contexto:[{amb:'Nacional',t:'En el páramo de Sumapaz el agua se congela por la noche y se funde en el día; en la costa Caribe la misma agua se evapora con el calor del mediodía.'},{amb:'Local',t:'La olla a presión cocina más rápido porque el agua hierve a unos 120 °C bajo mayor presión.'}],
  cotidianos:['Un charco que se seca, un espejo que se empaña y una vela que se derrite son cambios de estado; quemar un papel o freír un huevo son cambios químicos.'],
  activacion:['¿Por qué las papas tardan más en cocinarse en Bogotá que en Cartagena? ¿Cómo sabes que quemar un papel es distinto a romperlo?']},
 ['La <strong>materia</strong> se presenta en tres estados: en el <strong>sólido</strong> las partículas ocupan posiciones fijas y vibran; en el <strong>líquido</strong> están juntas pero se deslizan; en el <strong>gas</strong> están muy separadas y se mueven libremente. Al calentar, las partículas ganan energía y se produce un <strong>cambio de estado</strong>: fusión, evaporación, sublimación; al enfriar: condensación, solidificación, deposición. La evaporación ocurre en la superficie a cualquier temperatura; la ebullición, en todo el líquido al llegar al punto de ebullición. Mientras una sustancia pura funde o hierve, su temperatura permanece constante.',
  'La <strong>temperatura</strong> y la <strong>presión</strong> modifican el punto de ebullición: a menor presión (la altura) hierve a menos temperatura; a mayor presión (olla a presión) hierve a más. Otras propiedades físicas (densidad, solubilidad, viscosidad) se miden sin cambiar la sustancia.',
  'En un <strong>cambio físico</strong> no se forman sustancias nuevas (fundir hielo, disolver azúcar). En un <strong>cambio químico</strong> los átomos se reorganizan y aparecen sustancias nuevas: se desprende un gas, aparece un sólido, cambia el color o se libera energía.'],
 {raiz:'Materia',ramas:[{t:'Estados',items:['Sólido, líquido y gas','Modelo de partículas']},{t:'Cambios de estado',items:['Fusión, evaporación, sublimación','Condensación, solidificación']},{t:'T y P',items:['Punto de ebullición vs. presión','Olla a presión y altura']},{t:'Físico o químico',items:['Sustancias nuevas','Evidencias: gas, color, sólido, calor']}]},
 {f:'¿Por qué el agua hierve a 92 °C en Bogotá?',partes:[['Presión en Bogotá ≈ 0,74 atm','cat','menos presión exterior sobre el líquido'],['Menos energía para escapar','ox','las moléculas necesitan menos energía para pasar a gas'],['PE ≈ 92 °C','an','el agua hierve a menor temperatura y las papas se cocinan más lento']]}),
tema('mezclas','Mezclas y separación',
 {curiosos:['El aire que respiras es una mezcla de gases, y el agua de la llave contiene sales y gases disueltos: ninguna es una sustancia pura.','La sal de Zipaquirá y la de Manaure se obtienen separando una mezcla: con minería de roca y con evaporación del agua de mar.'],
  contexto:[{amb:'Nacional',t:'En las salinas marinas de Manaure (La Guajira) el agua de mar se evapora al sol y la sal cristaliza.'},{amb:'Local',t:'Las plantas de potabilización usan sedimentación y filtración; en el barequeo del oro se aprovecha la densidad del metal.'}],
  cotidianos:['Colar el tinto, sacudir la harina por un cedazo y separar la grasa del caldo son técnicas de separación de mezclas.'],
  activacion:['¿Cómo recuperarías la sal de un vaso de agua salada? ¿Y la arena de un vaso de agua con arena? ¿Son la misma técnica?']},
 ['Una <strong>sustancia pura</strong> tiene composición fija: un <strong>elemento</strong> (Cu) o un <strong>compuesto</strong> (H₂O). Una <strong>mezcla</strong> tiene varios componentes que conservan sus propiedades; es <strong>homogénea</strong> si se ve una sola fase y <strong>heterogénea</strong> si se ven dos o más. Los <strong>coloides</strong> (leche, gelatina, pinturas) tienen partículas dispersas que no sedimentan y dispersan la luz (efecto Tyndall).',
  'Se separan por métodos físicos que aprovechan una propiedad: <strong>filtración</strong> (sólido insoluble y líquido), <strong>decantación</strong> (líquidos inmiscibles), <strong>tamizado</strong> (tamaño de partícula), <strong>evaporación y cristalización</strong> (sólido disuelto), <strong>destilación</strong> (distinto punto de ebullición), imantación y cromatografía.',
  'El <strong>agua</strong> es un solvente muy bueno: transporta nutrientes y desechos en los seres vivos y disuelve sales y azúcares.'],
 {raiz:'Materia',ramas:[{t:'Sustancias puras',items:['Elementos','Compuestos']},{t:'Mezclas',items:['Homogéneas (soluciones)','Heterogéneas y coloides']},{t:'Separación',items:['Filtración, decantación, tamizado','Evaporación y destilación']}]},
 {f:'Separar arena, sal y agua',partes:[['Filtrar','cat','la arena queda retenida; la sal pasa disuelta'],['Evaporar el filtrado','ox','el agua se va como vapor'],['Recoger la sal','an','los cristales de sal quedan en el recipiente']]}),
tema('intermoleculares','Fuerzas intermoleculares',
 {curiosos:['El agua hierve a 100 °C y el H₂S, que es más pesado, a −60 °C: la diferencia son los puentes de hidrógeno.','Los insectos zapateros caminan sobre el agua porque los puentes de hidrógeno forman una «piel» en la superficie.'],
  contexto:[{amb:'Nacional',t:'Los páramos capturan la neblina porque el agua se adhiere y se atrae a las hojas de los frailejones.'},{amb:'Local',t:'El jabón limpia la grasa porque su cola apolar se une al aceite y su cabeza polar al agua.'}],
  cotidianos:['La gasolina se evapora más rápido que el aceite de cocina; el hielo flota; el alcohol se mezcla con agua y el aceite no.'],
  activacion:['¿Qué se rompe cuando el agua hierve: los enlaces O–H o las atracciones entre moléculas? ¿Por qué el aceite no se mezcla con agua?']},
 ['Las <strong>fuerzas intermoleculares</strong> son atracciones entre moléculas, mucho más débiles que los enlaces dentro de ellas. De menor a mayor: <strong>dispersión de London</strong> (todas las moléculas; dipolos instantáneos), <strong>dipolo-dipolo</strong> (moléculas polares) y <strong>puente de hidrógeno</strong> (H unido a F, O o N).',
  'A mayor fuerza intermolecular, mayor punto de ebullición y de fusión, menor volatilidad y mayor tensión superficial y viscosidad. Dentro de una familia, la fuerza de London crece con el tamaño de la molécula (halógenos, alcanos).',
  'La regla <strong>«semejante disuelve a semejante»</strong>: lo polar se disuelve en solventes polares (agua) y lo apolar en apolares (hexano). Por eso la sal y el etanol se disuelven en agua y el aceite no.'],
 {raiz:'Fuerzas intermoleculares',ramas:[{t:'Tipos',items:['London','Dipolo-dipolo','Puente de hidrógeno']},{t:'Efectos',items:['Punto de ebullición','Viscosidad y tensión superficial']},{t:'Solubilidad',items:['Semejante disuelve a semejante']}]},
 {f:'¿Por qué el agua hierve a 100 °C y el H₂S a −60 °C?',partes:[['H₂O: O muy electronegativo','cat','forma puentes de hidrógeno'],['H₂S: S menos electronegativo','ox','casi no forma puentes de hidrógeno'],['Más energía para separar el agua','an','por eso su punto de ebullición es mayor']]}),
tema('precipitacion','Precipitación y redox',
 {curiosos:['El sulfato de bario (insoluble) se bebe para las radiografías del estómago; el cloruro de bario es un veneno.','El sarro de las ollas es carbonato de calcio que precipita al calentar agua dura.'],
  contexto:[{amb:'Nacional',t:'Los hornos de cal de Boyacá descomponen la caliza (CaCO₃) en cal viva (CaO) y CO₂.'},{amb:'Local',t:'Los antiácidos (Mg(OH)₂) neutralizan el exceso de HCl del estómago.'}],
  cotidianos:['El óxido de una reja y la pila de un control remoto son redox; el sarro de la olla es precipitación; el antiácido después de una comida es neutralización.'],
  activacion:['Al mezclar dos soluciones transparentes aparece un sólido: ¿qué pasó? ¿Cómo se sabe que una reacción es redox?']},
 ['En una <strong>reacción de precipitación</strong> dos soluciones de sales solubles forman un <strong>sólido insoluble</strong> (precipitado). Se predice con las reglas de solubilidad: nitratos y sales de Na⁺, K⁺ y NH₄⁺ son solubles; los cloruros y sulfatos también, salvo AgCl, PbCl₂, BaSO₄ y PbSO₄; los carbonatos, hidróxidos y sulfuros son insolubles, salvo los de Na⁺, K⁺ y NH₄⁺ (CaCO₃ es insoluble). La <strong>ecuación iónica neta</strong> solo muestra los iones que forman el sólido; los demás son <strong>iones espectadores</strong>.',
  'En una reacción <strong>redox</strong> se transfieren electrones: el <strong>reductor</strong> se oxida (pierde e⁻) y el <strong>oxidante</strong> se reduce (gana e⁻). Se detecta porque cambian los estados de oxidación. La pila galvánica aprovecha esa transferencia para producir corriente.',
  'En la <strong>neutralización</strong> un ácido y una base forman una sal y agua; en la <strong>descomposición</strong> un compuesto se rompe en dos o más sustancias.'],
 {raiz:'Mecanismos de reacción',ramas:[{t:'Precipitación',items:['Reglas de solubilidad','Ecuación iónica neta']},{t:'Redox',items:['Oxidación y reducción','Agente oxidante y reductor']},{t:'Neutralización',items:['Ácido + base → sal + agua']},{t:'Descomposición',items:['Un reactivo, varios productos']}]},
 {f:'AgNO₃ + NaCl → ?',partes:[['Ag⁺ + Cl⁻','cat','iones que se encuentran'],['AgCl es insoluble','ox','por la regla de solubilidad de los cloruros'],['Ag⁺ + Cl⁻ → AgCl(s)','an','ecuación iónica neta; Na⁺ y NO₃⁻ son espectadores']]}),
tema('termo','Energía en las reacciones',
 {curiosos:['Las bolsas de frío instantáneo se enfrían porque el nitrato de amonio absorbe calor al disolverse.','El convertidor catalítico de los carros usa platino y rodio para acelerar reacciones que limpian el escape.'],
  contexto:[{amb:'Nacional',t:'En las termoeléctricas a gas y a carbón de la costa Caribe (como las que usan carbón del Cerrejón) se aprovecha el calor liberado en la combustión para generar electricidad.'},{amb:'Local',t:'La nevera conserva los alimentos porque al enfriar disminuye la rapidez de las reacciones de descomposición.'}],
  cotidianos:['Encender una estufa de gas (exotérmica), cocinar un huevo, usar una bolsa de frío instantáneo y la acción de las enzimas de la saliva.'],
  activacion:['¿Por qué un fósforo necesita que lo frotes para encender? ¿Por qué las reacciones son más lentas en la nevera?']},
 ['Una reacción es <strong>exotérmica</strong> si libera calor (ΔH &lt; 0): los productos tienen menos energía que los reactivos. Es <strong>endotérmica</strong> si absorbe calor (ΔH &gt; 0). La cantidad de calor se mide como Q = m·c·ΔT.',
  'Para que ocurra una reacción los choques deben superar la <strong>energía de activación</strong> (Ea). La rapidez aumenta con la temperatura, la concentración y la superficie de contacto.',
  'Un <strong>catalizador</strong> acelera la reacción al ofrecer un camino con menor Ea; no cambia ΔH ni la cantidad de producto y no se consume. Las enzimas son catalizadores biológicos.'],
 {raiz:'Energía y reacciones',ramas:[{t:'Calor',items:['Exotérmica (ΔH < 0)','Endotérmica (ΔH > 0)']},{t:'Barrera',items:['Energía de activación','Diagrama de energía']},{t:'Rapidez',items:['Temperatura, concentración, superficie','Catalizadores y enzimas']}]},
 {f:'¿Cuánto calor para calentar 200 g de agua de 20 a 30 °C?',partes:[['Q = m·c·ΔT','cat','fórmula del calor'],['200 g × 4,18 J/g·°C × 10 °C','ox','se reemplazan los datos'],['Q = 8360 J','an','calor absorbido por el agua']]}),
tema('ambiente','Química del ambiente',
 {curiosos:['El CO₂ atmosférico pasó de unas 280 ppm antes de la Revolución Industrial a más de 410 ppm hoy.','Los páramos colombianos almacenan carbono y agua: conservarlos ayuda al clima y al agua de millones de personas.'],
  contexto:[{amb:'Nacional',t:'Los glaciares del Cocuy, la Sierra Nevada de Santa Marta y el Ruiz han perdido buena parte de su área en las últimas décadas; son pequeños y aportan poco al caudal nacional, pero su retroceso es un indicador del calentamiento.'},{amb:'Local',t:'La lluvia ácida se forma cuando el SO₂ y los NOₓ de industrias y vehículos reaccionan con el agua.'}],
  cotidianos:['Cada vez que se enciende un motor o una estufa de gas se libera CO₂; cada árbol sembrado captura algo de ese CO₂ por fotosíntesis.'],
  activacion:['¿Por qué un invernadero es más cálido que el exterior? ¿Qué relación tiene con el planeta?']},
 ['El <strong>efecto invernadero</strong> es natural: gases como el CO₂, el CH₄ y el vapor de agua absorben parte de la radiación infrarroja que emite la superficie y la devuelven, y así la Tierra es habitable. La quema de combustibles fósiles, la deforestación y la ganadería lo <strong>intensifican</strong> y causan el calentamiento global.',
  'El <strong>ciclo del carbono</strong> conecta la fotosíntesis (6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂) con la respiración y la combustión; el <strong>ciclo del nitrógeno</strong> incluye la fijación del N₂ por bacterias; el <strong>ciclo del agua</strong> depende de los cambios de estado.',
  'Los óxidos de azufre y de nitrógeno producen <strong>lluvia ácida</strong>; el exceso de fertilizantes nitrogenados produce <strong>eutrofización</strong>.'],
 {raiz:'Ambiente',ramas:[{t:'Efecto invernadero',items:['CO₂, CH₄, H₂O','Calentamiento global']},{t:'Ciclos',items:['Carbono','Nitrógeno','Agua']},{t:'Impactos',items:['Lluvia ácida','Eutrofización','Retroceso glaciar']}]},
 {f:'¿Cuántos g de CO₂ salen de quemar 32 g de CH₄?',partes:[['32 g ÷ 16 g/mol = 2 mol','cat','moles de metano'],['1 mol CH₄ → 1 mol CO₂','ox','relación de la ecuación CH₄ + 2 O₂ → CO₂ + 2 H₂O'],['2 mol × 44 g/mol = 88 g','an','gramos de CO₂ liberados']]})
];

